                    Active = false,
                    Text = "",
                    AutoButtonColor = false,
                    Position = UDim2.new(0, 10, 0, 30),
                    Size = UDim2.new(1, -20, 1, -40),
                    Selectable = false,
                    BorderSizePixel = 0,
                    BackgroundColor3 = Library.Theme["Section"]
                }):AddToTheme({ BackgroundColor3 = 'Section' })

                Library:Create("UIStroke", {
