MODS["Utility"] = [====[
--[[
    Utility.lua
    Purpose:
        Shared utility helpers for Outlaw modules (instance creation, colors, formatting).
]]
local Workspace = cloneref(game.GetService(game, "Workspace"));
local Players = cloneref(game.GetService(game, "Players"));
local Client = Players.LocalPlayer;

local Utility = {};
Utility.__index = Utility;

local MathFloor = math.floor;
local MathClamp = math.clamp or function(Value, Min, Max)
    if Value < Min then
        return Min
    end
    if Value > Max then
        return Max
    end
    return Value
end;

function Utility:Instance(ClassName, Properties)
    if type(ClassName) ~= "string" then
        return nil
    end
    local Object = Instance.new(ClassName)
    if type(Properties) == "table" then
        for Property, Value in next, Properties do
            if Property == "Parent" then
                Object.Parent = Value
            else
                pcall(function()
                    Object[Property] = Value
                end)
            end
        end
    end
    return Object
end;

function Utility:DisconnectConnections(Connections)
    if type(Connections) ~= "table" then
        return
    end
    for Index = #Connections, 1, -1 do
        local Connection = Connections[Index]
        if typeof(Connection) == "RBXScriptConnection" then
            pcall(function()
                Connection:Disconnect()
            end)
        end
        Connections[Index] = nil
    end
end;

function Utility:FormatHoursMinutes(Seconds)
    Seconds = tonumber(Seconds) or 0
    local TotalMinutes = MathFloor((Seconds + 0.5) / 60)
    local Hours = MathFloor(TotalMinutes / 60)
    local Minutes = TotalMinutes % 60
    local TimeString = ("%dh %02dm"):format(Hours, Minutes)
    return Hours, Minutes, TimeString
end;

function Utility:ColorToRichRGB(Color)
    if typeof(Color) ~= "Color3" then
        return "rgb(255,255,255)"
    end
    local R = MathClamp(MathFloor(Color.R * 255 + 0.5), 0, 255)
    local G = MathClamp(MathFloor(Color.G * 255 + 0.5), 0, 255)
    local B = MathClamp(MathFloor(Color.B * 255 + 0.5), 0, 255)
    return ("rgb(%d,%d,%d)"):format(R, G, B)
end;

function Utility:SetIndicatorRow(Element, Text)
    if not Element then
        return
    end
    local Target = (type(Element) == "table" and Element.Instance) or Element
    if typeof(Target) == "Instance" and Target:IsA("TextLabel") and type(Text) == "string" then
        Target.RichText = true
        Target.Text = Text
    end
end;

function Utility:LerpColor(BaseColor, TargetColor, Blend)
    if typeof(BaseColor) ~= "Color3" then
        BaseColor = Color3.new(1, 1, 1)
    end
    if typeof(TargetColor) ~= "Color3" then
        TargetColor = BaseColor
    end
    Blend = MathClamp(tonumber(Blend) or 0, 0, 1)
    local R = BaseColor.R + (TargetColor.R - BaseColor.R) * Blend
    local G = BaseColor.G + (TargetColor.G - BaseColor.G) * Blend
    local B = BaseColor.B + (TargetColor.B - BaseColor.B) * Blend
    return Color3.new(R, G, B)
end;

_G.Utility = Utility;
return Utility;
