local Order = { "Directory", "Fonts", "Sounds", "Library", "Entities", "Targeting", "Visuals", "Ray", "Animations", "Env", "Utility" }
local Results = {}
for _, Name in ipairs(Order) do
    local Code = MODS[Name]
    local fn, err = loadstring(Code)
    if not fn then error("[outlaw_all] loadstring failed for " .. Name .. ": " .. tostring(err)) end
    local ok, res = pcall(fn)
    if not ok then error("[outlaw_all] exec failed for " .. Name .. ": " .. tostring(res)) end
    Results[Name] = res
end
local Library = _G.Library or Results.Library
local Toggles = _G.Toggles or (Library and Library.Toggles) or {}
local Options = _G.Options or (Library and Library.Options) or {}
return Library, Toggles, Options
