    local function InlineLoadOutlawCore()
        local fn, Err = loadstring(InlineOutlawCore, "=outlaw_all_embedded")
        if not fn then error(tostring(Err), 0) end
local Ok, Lib, Tog, Opt = pcall(fn)
        if Ok and Lib then return Lib, Tog, Opt end
        if not Ok then error('[bundle] InlineLoadOutlawCore pcall: ' .. tostring(Lib), 0) end
        error('[bundle] InlineLoadOutlawCore returned nil library', 0)
    end

local ModulePaths = {
    "outlaw/file/%s.lua",
    "outlaw/Modules/%s.lua",
    "%s.lua",
}

local function ReadModule(Name)
    for _, Tpl in ipairs(ModulePaths) do
        local Path = Tpl:format(Name)
        local Ok, Source = pcall(readfile, Path)
        if Ok and type(Source) == "string" and #Source > 16 then
            local fn, FErr = loadstring(Source)
            if fn then
                local Ok2, Mod = pcall(fn)
                if Ok2 and Mod then
                    return Mod
                end
            end
        end
    end
    return nil
end

local HttpService = game:GetService("HttpService")

-- Load the self-contained bundle of every module (outlaw_all.lua).
local function LoadBundle(FileName)
    local paths = {
        "outlaw/file/" .. FileName,
        "outlaw/" .. FileName,
        FileName,
        "outlaw/" .. FileName,
    }
    for _, Path in ipairs(paths) do
        local Ok, Source = pcall(readfile, Path)
        if Ok and type(Source) == "string" and #Source > 16 then
            local fn, FErr = loadstring(Source)
            if fn then
                local Ok2, Lib, Tog, Opt = pcall(fn)
                if Ok2 and Lib then
                    return Lib, Tog, Opt
                end
            end
        end
    end
    return nil
end

local Directory, Fonts, Library
do
    local Lib, Tog, Opt = InlineLoadOutlawCore()
    if Lib ~= nil and Lib then
        Library = Lib
        Directory = _G.Directory
        Fonts = _G.Fonts
    end
end
if not Directory then Directory = _G.Directory or ReadModule("Directory") end
if not Fonts     then Fonts     = ReadModule("Fonts") end
if not Library then
    Library = ReadModule("Library")
end

if not Library or not Library.Window then
    error("[adapter] Failed to load Outlaw Library module (tried outlaw/file/, outlaw/Modules/, root, GitHub)", 0)
end

_G.Modules  = _G.Modules  or {}
_G.Modules.Library = Library
_G.Modules.Directory = Directory or _G.Directory
_G.Library = Library
_G.Flags   = Library.Flags or {}
getgenv().Flags = _G.Flags

-- NH Library.Slider uses Dropdown.MaxSize in SetOpen but never defines it;
-- compute it from the option count so dropdowns can actually open. The rest of
-- the dropdown UI (row height, stock 20px bottom button) is left exactly as
-- the stock library ships it.
if type(Library.Dropdown) == "function" then
    local OrigDropdown = Library.Dropdown
    Library.Dropdown = function(Self, Params)
        local DD = OrigDropdown(Self, Params)
        if DD and type(DD) == "table" then
            if not DD.MaxSize then
                local Count = 0
                if type(Params) == "table" then
                    local It = Params.Items or Params.items
                    if type(It) == "table" then
                        Count = #It
                    end
                end
                DD.MaxSize = math.max(28, Count * 18 + 14)
            end
            -- the library positions the option list ALWAYS below the button. When the
            -- button sits near the bottom of the screen the list gets cut off.
            -- Flip it above the button when there isn't enough room underneath.
            if type(DD.SetOpen) == "function" then
                local OrigSetOpen = DD.SetOpen
                DD.SetOpen = function(self, Bool, ...)
                    local Res = OrigSetOpen(self, Bool, ...)
                    if Bool then
                        pcall(function()
                            local OH = DD.Items and DD.Items["OptionHolder"]
                                and DD.Items["OptionHolder"].Instance
                            local RD = DD.Items and DD.Items["RealDropdown"]
                                and DD.Items["RealDropdown"].Instance
                            if not OH or not RD then return end
                            local MaxH = DD.MaxSize or 120
                            local Cam = workspace and workspace.CurrentCamera
                            local VpY = Cam and Cam.ViewportSize or Vector2.new(1280, 720)
                            local GuiInset = game:GetService("GuiService"):GetGuiInset().Y + 10
                            local RdY = RD.AbsolutePosition.Y
                            local SpaceBelow = VpY.y - (RdY + RD.AbsoluteSize.Y + GuiInset + MaxH)
                            if SpaceBelow < 16 then
                                local X = RD.AbsolutePosition.X
                                local Y = math.max(GuiInset, RdY - MaxH)
                                local NewTween = game:GetService("TweenService"):Create(OH,
                                    TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                                        Position = UDim2.new(0, X, 0, Y),
                                    })
                                NewTween:Play()
                            end
                        end)
                    end
                    return Res
                end
            end
        end
        return DD
    end
end

-- Custom font: SmallestPixel/Minecraftia from the Fonts module.
if Fonts and type(Fonts.Cache) == "table" then
    if Fonts.Cache["SmallestPixel"] then
        Library.Font = Fonts.Cache["SmallestPixel"]
    elseif Fonts.Cache["Minecraftia"] then
        Library.Font = Fonts.Cache["Minecraftia"]
    end
end
Library.Fonts = Fonts or nil

-- Default theme override: applied on load so every script sees the same look.
if type(Library.Theme) == "table" then
    local DefTheme = {
        ["Outline"]        = Color3.fromRGB(25, 26, 28),
        ["Light Border"]   = Color3.fromRGB(255, 0, 255),
        ["Text"]           = Color3.fromRGB(255, 255, 255),
        ["Border"]         = Color3.fromRGB(31, 32, 33),
        ["Element"]        = Color3.fromRGB(28, 29, 35),
        ["Slider"]         = Color3.fromRGB(255, 255, 255),
        ["Inactive Text"]  = Color3.fromRGB(100, 100, 100),
        ["Hovered Element"]= Color3.fromRGB(36, 38, 45),
        ["Section"]        = Color3.fromRGB(20, 21, 25),
        ["Border 2"]       = Color3.fromRGB(5, 10, 14),
        ["Background"]     = Color3.fromRGB(16, 17, 20),
        ["Risky"]          = Color3.fromRGB(255, 50, 50),
        ["Accent"]         = Color3.fromRGB(158, 0, 255),
    }
    for Key, Color in pairs(DefTheme) do
        Library.Theme[Key] = Color
    end
