-- Slider fill colour: separate theme key "Slider" (defaults to Accent) so the
-- menu can retint slider fill areas without touching the global accent.
-- Shared with the adapter's own CreateOutLawSlider fills below.
pcall(function()
    Library.Theme = Library.Theme or {}
    if not Library.Theme["Slider"] then
        Library.Theme["Slider"] = Library.Theme["Accent"] or Color3.fromRGB(152, 188, 255)
    end
end)
local SliderTint = {
    Color = (Library.Theme and Library.Theme["Slider"]) or Color3.fromRGB(152, 188, 255),
    Fills = {},
}
local function PaintSliderFill(Fill)
    if not Fill or not Fill.Parent then return end
    local C = SliderTint.Color
    Fill.BackgroundColor3 = C
    pcall(function()
        local Grad = Fill:FindFirstChildOfClass("UIGradient")
        if Grad then
            Grad.Color = ColorSequence.new(
                Color3.new(math.min(1, C.R), math.min(1, C.G), math.min(1, C.B)),
                Color3.new(math.min(1, C.R * 0.67), math.min(1, C.G * 0.67), math.min(1, C.B * 0.67))
            )
        end
    end)
end
local function RegisterSliderFill(Fill)
    if not Fill then return end
    PaintSliderFill(Fill)
    table.insert(SliderTint.Fills, Fill)
end
local function RepaintAllSliderFills()
    for _, Fill in ipairs(SliderTint.Fills) do
        pcall(PaintSliderFill, Fill)
    end
end
if type(Library.Slider) == "function" then
    local OrigSliderFn = Library.Slider
    Library.Slider = function(Self, Params)
        local Sl = OrigSliderFn(Self, Params)
        pcall(function()
            if Sl and Sl.Items and Sl.Items["Accent"] and Sl.Items["Accent"].Instance then
                RegisterSliderFill(Sl.Items["Accent"].Instance)
            end
        end)
        return Sl
    end
end
if type(Library.ChangeTheme) == "function" then
    local OrigChangeThemeFn = Library.ChangeTheme
    Library.ChangeTheme = function(Self, Theme, Color)
        local Ok, Res = pcall(OrigChangeThemeFn, Self, Theme, Color)
        if Theme == "Slider" then
            SliderTint.Color = Color
        end
        if Theme == "Slider" or Theme == "Accent" then
            RepaintAllSliderFills()
        end
        return Res
    end
end

adapter = {
    ScreenGui = (Library.Holder and Library.Holder.Instance) or nil,
}

local Toggles = {}
local Options = {}
local AllDepBoxes = {}

local Flags = Library.Flags or _G.Flags
local SetFlags = Library.SetFlags or {}

-- Bridge Library.Flags writes back into our wrapper mirror objects (config loads).
local function Bridge(Flag, Obj)
    local OriginalSetter = SetFlags[Flag]
    if OriginalSetter then
        SetFlags[Flag] = function(Value)
            pcall(OriginalSetter, Value)
            Obj.Value = Value
            if Obj._cbs then
                for _, CB in ipairs(Obj._cbs) do
                    pcall(CB, Value)
                end
            end
        end
    end
    if Flags[Flag] ~= nil then
        Obj.Value = Flags[Flag]
    end
end

local function MakeCommon(Obj)
    function Obj:SetEnabled(v)
        self.Enabled = (v ~= false)
        if self._el and self._el.SetVisibility then
            pcall(function() self._el:SetVisibility(self.Enabled) end)
        end
    end
    function Obj:SetTitle(t)
        if self._el and self._el.SetText then
            pcall(function() self._el:SetText(t) end)
        end
    end
    return Obj
end

-- Forward-declared; auto-refreshes every DependencyBox when any control changes.
local SafeUpdateDeps = function() end

-- Wraps a user callback so library clicks also refresh our mirror + OnChanged hooks.
local function ChainCallback(Obj, UserCb)
    return function(Value)
        if type(Obj) == "table" then
            Obj.Value = Value
            if Obj._cbs then
                for _, CB in ipairs(Obj._cbs) do
                    pcall(CB, Value)
                end
            end
        end
        if UserCb then pcall(UserCb, Value) end
        SafeUpdateDeps()
    end
end

-- Self-contained Linoria-style colourpicker.  Builds its own popup so we no
-- longer depend on the broken native SetOpen / Debounce path at all.
local UIS = game:GetService("UserInputService")
local function CreateLinoriaCp(Flag, DefaultColor, OnChangeCb)
    DefaultColor = (typeof(DefaultColor) == "Color3") and DefaultColor or Color3.new(1,1,1)

    local ScreenGui = adapter and adapter.ScreenGui
    if not ScreenGui then ScreenGui = Library.Holder and Library.Holder.Instance end

    local Cp = {
        Value   = DefaultColor,
        IsOpen  = false,
        Flag    = Flag,
        _cbs    = {},
    }

    local Make = function(Class, Props)
        local Inst = Instance.new(Class)
        for K, Val in pairs(Props) do
            if K ~= "Parent" then pcall(function() Inst[K] = Val end) end
        end
        if Props.Parent then Inst.Parent = Props.Parent end
        return Inst
    end

    local DarkerColor = function(C)
        return Color3.new(C.R * 0.65, C.G * 0.65, C.B * 0.65)
    end

    local GuiInsetY = 0
    pcall(function() GuiInsetY = game:GetService("GuiService"):GetGuiInset().Y end)

    local Hue, Sat, Vib = Color3.toHSV(DefaultColor)

