    })

    local SatVibMapInner = Make("Frame", {
        BackgroundColor3 = Color3.fromRGB(30, 30, 30),
        BorderColor3     = Color3.fromRGB(20, 20, 20),
        BorderMode       = Enum.BorderMode.Inset,
        Size             = UDim2.new(1, 0, 1, 0),
