    local HueCursor = Make("Frame", {
        BackgroundColor3 = Color3.new(1, 1, 1);
        AnchorPoint      = Vector2.new(0, 0.5);
        BorderColor3     = Color3.new(0, 0, 0);
        Size             = UDim2.new(1, 0, 0, 1);
        ZIndex           = 254,
        Parent           = HueSelectorInner;
    })

    -- hex box
    local HueBoxOuter = Make("Frame", {
        BorderColor3 = Color3.new(0, 0, 0),
        Position     = UDim2.fromOffset(4, 228),
        Size         = UDim2.new(0.5, -6, 0, 20),
        ZIndex       = 253,
        Parent       = PickerFrameInner,
    })

    local HueBoxInner = Make("Frame", {
        BackgroundColor3 = Color3.fromRGB(35, 35, 35),
        BorderColor3     = Color3.fromRGB(20, 20, 20),
        BorderMode       = Enum.BorderMode.Inset,
        Size             = UDim2.new(1, 0, 1, 0),
        ZIndex           = 254,
        Parent           = HueBoxOuter,
    })

    local HexBox = Make("TextBox", {
        BackgroundTransparency  = 1,
        Position                = UDim2.new(0, 5, 0, 0),
        Size                    = UDim2.new(1, -5, 1, 0),
        Font                    = Enum.Font.Code,
        PlaceholderColor3       = Color3.fromRGB(120, 120, 120),
        PlaceholderText         = "Hex color",
        Text                    = "#" .. DefaultColor:ToHex(),
        TextColor3              = Color3.new(1, 1, 1),
        TextSize                = 14,
        TextStrokeTransparency  = 0,
        TextXAlignment          = Enum.TextXAlignment.Left,
        ZIndex                  = 255,
        ClearTextOnFocus        = false,
        Parent                  = HueBoxInner,
    })

    -- rgb box
    local RgbBoxOuter = Make("Frame", {
        BorderColor3 = Color3.new(0, 0, 0),
        Position     = UDim2.new(0.5, 2, 0, 228),
        Size         = UDim2.new(0.5, -6, 0, 20),
        ZIndex       = 253,
        Parent       = PickerFrameInner,
    })

    local RgbBoxInner = Make("Frame", {
        BackgroundColor3 = Color3.fromRGB(35, 35, 35),
        BorderColor3     = Color3.fromRGB(20, 20, 20),
        BorderMode       = Enum.BorderMode.Inset,
        Size             = UDim2.new(1, 0, 1, 0),
        ZIndex           = 254,
        Parent           = RgbBoxOuter,
    })

    local RgbBox = Make("TextBox", {
        BackgroundTransparency  = 1,
        Position                = UDim2.new(0, 5, 0, 0),
        Size                    = UDim2.new(1, -5, 1, 0),
        Font                    = Enum.Font.Code,
        PlaceholderColor3       = Color3.fromRGB(120, 120, 120),
        PlaceholderText         = "RGB color",
        Text                    = ("%d, %d, %d"):format(
            math.floor(DefaultColor.R * 255),
            math.floor(DefaultColor.G * 255),
            math.floor(DefaultColor.B * 255)),
        TextColor3              = Color3.new(1, 1, 1),
        TextSize                = 14,
        TextStrokeTransparency  = 0,
        TextXAlignment          = Enum.TextXAlignment.Left,
        ZIndex                  = 255,
        ClearTextOnFocus        = false,
        Parent                  = RgbBoxInner,
    })

    -- right-click context menu
    local CtxFrame = Make("Frame", {
        BorderColor3 = Color3.new(),
        ZIndex       = 248,
        Visible      = false,
        Parent       = ScreenGui,
    })

    local CtxInner = Make("Frame", {
        BackgroundColor3 = Color3.fromRGB(30, 30, 30),
        BorderColor3     = Color3.fromRGB(60, 60, 60),
        BorderMode       = Enum.BorderMode.Inset,
        Size             = UDim2.new(1, 0, 1, 0),
        ZIndex           = 249,
        Parent           = CtxFrame,
    })

    Make("UIListLayout", {
        FillDirection  = Enum.FillDirection.Vertical,
        SortOrder      = Enum.SortOrder.LayoutOrder,
        Parent         = CtxInner,
    })

    Make("UIPadding", {
        PaddingLeft    = UDim.new(0, 4),
        Parent         = CtxInner,
    })

    local function AddCtxOption(Str, Callback)
        local Btn = Make("TextButton", {
            Size                 = UDim2.new(1, 0, 0, 18),
            BackgroundTransparency = 1,
            Font                 = Enum.Font.Code,
            TextSize             = 13,
            Text                 = Str,
            TextColor3           = Color3.fromRGB(200, 200, 200),
            TextXAlignment       = Enum.TextXAlignment.Left,
            ZIndex               = 250,
            AutoButtonColor      = false,
            Parent               = CtxInner,
        })
        Btn.InputBegan:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                Callback()
            end
        end)
        Btn.MouseEnter:Connect(function()
            Btn.TextColor3 = Color3.fromRGB(100, 150, 255)
        end)
        Btn.MouseLeave:Connect(function()
            Btn.TextColor3 = Color3.fromRGB(200, 200, 200)
        end)
    end

    AddCtxOption("Copy color", function()
        Cp._clipboard = Color3.fromHSV(Hue, Sat, Vib)
        CtxFrame.Visible = false
    end)
    AddCtxOption("Paste color", function()
        if Cp._clipboard then
            Hue, Sat, Vib = Color3.toHSV(Cp._clipboard)
            Display()
            CtxFrame.Visible = false
        end
    end)
    AddCtxOption("Copy HEX", function()
        pcall(function() setclipboard("#" .. Color3.fromHSV(Hue, Sat, Vib):ToHex()) end)
        CtxFrame.Visible = false
    end)
    AddCtxOption("Copy RGB", function()
        local C = Color3.fromHSV(Hue, Sat, Vib)
        pcall(function() setclipboard(("%d, %d, %d"):format(
            math.floor(C.R * 255), math.floor(C.G * 255), math.floor(C.B * 255))) end)
        CtxFrame.Visible = false
    end)

    -- core display
    function Display()
        local C = Color3.fromHSV(Hue, Sat, Vib)
        Cp.Value = C
        SatVibMap.BackgroundColor3 = Color3.fromHSV(Hue, 1, 1)
        Swatch.BackgroundColor3 = C
        Swatch.BorderColor3 = DarkerColor(C)
        CursorOuter.Position = UDim2.new(Sat, 0, 1 - Vib, 0)
        HueCursor.Position = UDim2.new(0, 0, Hue, 0)
        HexBox.Text = "#" .. C:ToHex()
        RgbBox.Text = ("%d, %d, %d"):format(
            math.floor(C.R * 255), math.floor(C.G * 255), math.floor(C.B * 255))
        for _, CB in ipairs(Cp._cbs) do pcall(CB, C) end
        if OnChangeCb then pcall(OnChangeCb, C) end
    end

    -- SV drag (with GuiInset fix)
    SatVibMap.InputBegan:Connect(function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 then
            while UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
                local Mouse = UIS:GetMouseLocation()
                local MinX = SatVibMap.AbsolutePosition.X
                local MaxX = MinX + SatVibMap.AbsoluteSize.X
                local MinY = SatVibMap.AbsolutePosition.Y + GuiInsetY
                local MaxY = MinY + SatVibMap.AbsoluteSize.Y
                Sat = math.clamp((Mouse.X - MinX) / (MaxX - MinX), 0, 1)
                Vib = 1 - math.clamp((Mouse.Y - MinY) / (MaxY - MinY), 0, 1)
                Display()
                task.wait()
            end
        end
    end)

    -- Hue drag
    HueSelectorInner.InputBegan:Connect(function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 then
            while UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
                local Mouse = UIS:GetMouseLocation()
                local MinY = HueSelectorInner.AbsolutePosition.Y + GuiInsetY
                local MaxY = MinY + HueSelectorInner.AbsoluteSize.Y
                Hue = math.clamp((Mouse.Y - MinY) / (MaxY - MinY), 0, 1)
                Display()
                task.wait()
            end
        end
    end)

    -- hex/rgb input
    HexBox.FocusLost:Connect(function()
        local ok, C = pcall(Color3.fromHex, HexBox.Text)
        if ok and typeof(C) == "Color3" then
            Hue, Sat, Vib = Color3.toHSV(C)
            Display()
        end
    end)

    RgbBox.FocusLost:Connect(function()
        local r, g, b = RgbBox.Text:match("(%d+),%s*(%d+),%s*(%d+)")
        if r and g and b then
            Hue, Sat, Vib = Color3.toHSV(Color3.fromRGB(tonumber(r), tonumber(g), tonumber(b)))
            Display()
        end
    end)

    -- open/close
    function Cp:SetOpen(Bool)
        Cp.IsOpen = (Bool == true)
        if Cp.IsOpen then
            CtxFrame.Visible = false
            PickerFrameOuter.Visible = true
            local Btn = Cp._anchorBtn or Swatch
            if Btn and Btn.Parent then
                local P = Btn.AbsolutePosition
                local S = Btn.AbsoluteSize
                PickerFrameOuter.Position = UDim2.fromOffset(
                    math.floor(P.X),
                    math.floor(P.Y + S.Y + 10 + GuiInsetY)
                )
            end
            Display()
        else
            PickerFrameOuter.Visible = false
        end
    end

    function Cp:Toggle()
        self:SetOpen(not self.IsOpen)
    end

    function Cp:SetValue(C)
        if typeof(C) ~= "Color3" then return end
        Hue, Sat, Vib = Color3.toHSV(C)
        Display()
    end

    function Cp:OnChanged(fn)
        if type(fn) == "function" then table.insert(Cp._cbs, fn) end
        return self
    end

    Swatch.MouseButton1Click:Connect(function()
        Cp:Toggle()
    end)

    Swatch.MouseButton2Click:Connect(function()
        Cp._clipboard = Color3.fromHSV(Hue, Sat, Vib)
    end)

    -- click outside to close
    UIS.InputBegan:Connect(function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 then
            CtxFrame.Visible = false
            if not Cp.IsOpen then return end
            local Mouse = UIS:GetMouseLocation()
            local MY = Mouse.Y - GuiInsetY
            local AbsPos = PickerFrameOuter.AbsolutePosition
            local AbsSize = PickerFrameOuter.AbsoluteSize
            local OverPopup = (Mouse.X >= AbsPos.X and Mouse.X <= AbsPos.X + AbsSize.X
                and MY >= AbsPos.Y and MY <= AbsPos.Y + AbsSize.Y)
            local OverSwatch = (Mouse.X >= Swatch.AbsolutePosition.X
                and Mouse.X <= Swatch.AbsolutePosition.X + Swatch.AbsoluteSize.X
                and MY >= Swatch.AbsolutePosition.Y
                and MY <= Swatch.AbsolutePosition.Y + Swatch.AbsoluteSize.Y)
            if not OverPopup and not OverSwatch then
                Cp:SetOpen(false)
            end
        end
    end)

    Display()
    Cp.Swatch = Swatch
    Cp.Popup  = PickerFrameOuter
    return Cp
end


local function WrapToggle(El, Id, DefVal, UserCb)
    local Obj = MakeCommon({
        Value    = (DefVal == true),
        Enabled  = true,
        _el      = El,
        _id      = Id,
        _cbs     = {},
        _wrapped = true,
    })
    function Obj:SetValue(v)
        self.Value = (v == true)
        if self._el then pcall(function() self._el:Set(v) end) end
        SafeUpdateDeps()
    end
    function Obj:OnChanged(cb)
        if type(cb) == "function" then table.insert(self._cbs, cb) end
        return self
    end
    function Obj:AddKeyPicker(PickerId, Data)
        Data = Data or {}
        local SyncState = Data.SyncToggleState == true
        local UserCb = Data.Callback
        local Ready = false
        local KP = self._el:Keybind({
            Name     = Data.Text or (self._id .. "_bind"),
            Flag     = PickerId,
            Mode     = Data.Mode or "Toggle",
            Default  = Data.Default or "None",
            Callback = function(State)
                if Ready and SyncState and self._el and self._el.Set then
                    pcall(function() self._el:Set(State == true) end)
                end
                if type(UserCb) == "function" then pcall(UserCb, State) end
            end,
        })
        Ready = true
        local Picker = setmetatable({
            _el   = KP,
            _id   = PickerId,
            _cbs  = {},
            _wrapped = true,
        }, {
            __index = function(self, k)
                if k == "Mode" then
                    return KP and KP.Mode or (Data.Mode or "Toggle")
                elseif k == "State" then
                    return KP and KP.Toggled or false
                elseif k == "Value" then
                    return KP and KP.Key or Data.Default or "None"
                end
                return nil
            end,
            __newindex = function(self, k, v)
                if k == "Mode" and KP and KP.SetMode then
                    pcall(function() KP:SetMode(v) end)
                elseif k == "State" and KP and KP.SetToggled then
                    pcall(function() KP:SetToggled(v) end)
                elseif k == "_el" or k == "_id" or k == "_cbs" or k == "_wrapped" then
                    rawset(self, k, v)
                elseif k == "Value" and KP and KP.Set then
                    pcall(function() KP:Set(v) end)
                end
            end,
        })
        function Picker:SetValue(V)
            if self._el and self._el.Set then pcall(function() self._el:Set(V) end) end
        end
        function Picker:SetStatus(V)
            if self._el and self._el.SetToggled then
                pcall(function() self._el:SetToggled(V == true) end)
            end
        end
        function Picker:SetVisibility(V)
            if self._el and self._el.SetVisibility then
                pcall(function() self._el:SetVisibility(V) end)
            end
        end
        Toggles[PickerId] = Picker
        return Picker
    end
    function Obj:AddColorPicker(CpId, Data)
        Data = Data or {}
        local DefaultColor = Data.Default or Color3.new(1, 1, 1)
        local Cb = Data.Callback
        local LinCp = CreateLinoriaCp(CpId, DefaultColor, Cb)
        local NativeCp
        pcall(function()
            NativeCp = self._el:Colorpicker({
                Flag     = CpId,
                Default  = DefaultColor,
                Callback = function() end,
            })
        end)
        if NativeCp then
            local Btn = NativeCp.Items and NativeCp.Items["ColorpickerButton"]
                and NativeCp.Items["ColorpickerButton"].Instance
            if Btn then
                local Sw = LinCp.Swatch
                Sw.Size = UDim2.new(1, 0, 1, 0)
                Sw.Position = UDim2.new(0, 0, 0, 0)
                Sw.Parent = Btn
                LinCp._anchorBtn = Btn
                Btn.MouseButton1Click:Connect(function()
                    LinCp:Toggle()
                end)
            end
            local Win = NativeCp.Items and NativeCp.Items["ColorpickerWindow"]
                and NativeCp.Items["ColorpickerWindow"].Instance
            if Win then
                Win.Visible = false
                pcall(function() Win.Parent = game:GetService("CoreGui") end)
            end
        else
            local Parent = self._el and self._el.Items and self._el.Items.SubElements
                and self._el.Items.SubElements.Instance
            if Parent then LinCp.Swatch.Parent = Parent end
        end
        local Cp = { Value = DefaultColor, _id = CpId, _cbs = {}, _lin = LinCp }
        function Cp:SetValue(v)
            LinCp:SetValue(v)
            Cp.Value = LinCp.Value
            for _, fn in ipairs(Cp._cbs) do pcall(fn, Cp.Value) end
        end
        function Cp:OnChanged(cb)
            if type(cb) == "function" then table.insert(Cp._cbs, cb) end
            LinCp:OnChanged(function(Color)
                Cp.Value = Color
                for _, fn in ipairs(Cp._cbs) do pcall(fn, Color) end
            end)
            return self
        end
        Toggles[CpId] = Cp
        return self
    end
    Toggles[Id] = Obj
    Bridge(Id, Obj)
    return Obj
end

local function WrapSlider(El, Id, DefVal, UserCb)
    local Obj = MakeCommon({
        Value   = DefVal or 0,
        Enabled = true,
        _el     = El,
        _id     = Id,
        _cbs    = {},
        _wrapped = true,
    })
    function Obj:SetValue(v)
        self.Value = v
        if self._el then pcall(function() self._el:Set(v) end) end
        SafeUpdateDeps()
    end
    function Obj:OnChanged(cb)
        if type(cb) == "function" then table.insert(self._cbs, cb) end
        return self
    end
    Options[Id] = Obj
    Bridge(Id, Obj)
    return Obj
end

local function WrapDropdown(El, Id, DefVal, UserCb)
    local Obj = MakeCommon({
        Value   = DefVal,
        Enabled = true,
        _el     = El,
        _id     = Id,
        _cbs    = {},
        _wrapped = true,
    })
    function Obj:SetValue(v)
        self.Value = v
        if self._el then pcall(function() self._el:Set(v) end) end
        SafeUpdateDeps()
    end
    function Obj:OnChanged(cb)
        if type(cb) == "function" then table.insert(self._cbs, cb) end
        return self
    end
    function Obj:SetOptions(v) pcall(function() self._el:Refresh(v) end) end
    Options[Id] = Obj
    Bridge(Id, Obj)
    return Obj
end

local function WrapButton(El, TextVal)
    return MakeCommon({
        Value   = nil,
        Enabled = true,
        _el     = El,
        _wrapped = true,
        Fire = function(self2)
            if self2._el and self2._el.Press then
                pcall(function() self2._el:Press() end)
            end
        end,
    })
end

-- Same drag mechanics as NH (Sliding flag + UIS.InputChanged + fraction fill),
-- but the value text sits ON TOP of the track (always visible), not inside the
-- accent fill (which has 0 width at Default=0).
local CN_UIS = game:GetService("UserInputService")

local function CreatXRound(Number, Float)
    local N = tonumber(Number) or 0
    if N ~= N or math.abs(N) == math.huge then return 0 end
    local F = tonumber(Float) or 0
    if F <= 0 then return math.floor(N + 0.5) end
    local M = 10 ^ F
    return math.floor(N * M + 0.5) / M
end

local function CreateOutLawSlider(Section, Id, Data)
    Data = Data or {}
    local Container = Section.Items and Section.Items["Content"] and Section.Items["Content"].Instance
    if not Container then return nil end

    local Th = Library.Theme or {}
    local function C(Key, Fallback) return (Th[Key] ~= nil and Th[Key]) or (Fallback or Color3.new(0, 0, 0)) end

    local NumOf = function(X, Fallback)
        local N = tonumber(X)
        if not N or N ~= N or math.abs(N) == math.huge then return Fallback end
        return N
    end

    local Slider = {
        Name     = Data.Text or Id,
        Flag     = Data.Flag or Id,
        Default  = NumOf(Data.Default, 0),
        Min      = NumOf(Data.Min, 0),
        Max      = NumOf(Data.Max, 100),
        Suffix   = Data.Suffix or "",
        Tooltip  = Data.Tooltip,
        Callback = Data.Callback or function() end,
        Decimals = tonumber(Data.Decimals) or tonumber(Data.Rounding) or 0,
        Value    = 0,
        Sliding  = false,
        Items    = {},
    }
    if Slider.Max < Slider.Min then
        local Tmp = Slider.Max
        Slider.Max = Slider.Min
        Slider.Min = Tmp
    end

    local LabelEl, RealSlider, SliderFill, ValueLabel
    local InputChanged = nil

    do
        local Holder = Library:Create("Frame", {
            Name = "\0",
            Parent = Container,
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 25),
            BorderSizePixel = 0,
        })
        Slider.Items["Holder"] = Holder

        LabelEl = Library:Create("TextLabel", {
            Name = "\0",
            FontFace = Library.Font,
            TextSize = Library.FontSize,
            Parent = Holder.Instance,
            TextColor3 = C("Text", Color3.fromRGB(180, 180, 180)),
            Text = Slider.Name,
            BackgroundTransparency = 1,
            Size = UDim2.new(0, 0, 0, 12),
            BorderSizePixel = 0,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Center,
            AutomaticSize = Enum.AutomaticSize.X,
        })
        Slider.Items["Text"] = LabelEl

        RealSlider = Library:Create("TextButton", {
            Name = "\0",
            FontFace = Library.Font,
            TextSize = Library.FontSize,
            Parent = Holder.Instance,
            TextColor3 = Color3.fromRGB(0, 0, 0),
            Text = "",
            AutoButtonColor = false,
            AnchorPoint = Vector2.new(0, 1),
            Position = UDim2.new(0, 0, 1, 0),
            Size = UDim2.new(1, 0, 0, 6),
            BorderSizePixel = 0,
            BackgroundColor3 = C("Element", Color3.fromRGB(28, 29, 35)),
        })

        Library:Create("UIStroke", {
            Name = "\0",
            Parent = RealSlider.Instance,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            LineJoinMode = Enum.LineJoinMode.Miter,
            Color = C("Border", Color3.fromRGB(7, 8, 10)),
        })
        Slider.Items["RealSlider"] = RealSlider

        SliderFill = Library:Create("Frame", {
            Name = "\0",
            Parent = RealSlider.Instance,
            Size = UDim2.new(0, 0, 1, 0),
            BorderSizePixel = 0,
            BackgroundColor3 = C("Accent", Color3.fromRGB(152, 188, 255)),
        })
        Slider.Items["Accent"] = SliderFill

        Library:Create("UIGradient", {
            Name = "\0",
            Parent = SliderFill.Instance,
            Rotation = -90,
            Color = ColorSequence.new {
                ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(172, 172, 172)),
            },
        })

        RegisterSliderFill(SliderFill.Instance)

        ValueLabel = Library:Create("TextLabel", {
            Name = "\0",
            FontFace = Library.Font,
            TextSize = Library.FontSize,
            Parent = RealSlider.Instance,
            TextColor3 = C("Text", Color3.fromRGB(180, 180, 180)),
            Text = "0",
            AnchorPoint = Vector2.new(1, 0),
            Size = UDim2.new(0, 0, 0, 6),
            BackgroundTransparency = 1,
            Position = UDim2.new(1, -3, 0, 0),
            BorderSizePixel = 0,
            TextXAlignment = Enum.TextXAlignment.Right,
            TextYAlignment = Enum.TextYAlignment.Center,
            AutomaticSize = Enum.AutomaticSize.X,
        })
        Slider.Items["Value"] = ValueLabel

        Library:Create("UIStroke", {
            Name = "\0",
            Parent = ValueLabel.Instance,
            LineJoinMode = Enum.LineJoinMode.Miter,
        })
    end

    function Slider:GetSize(Input)
        local TrackX = RealSlider.Instance.AbsoluteSize.X
        if not Input or TrackX <= 0 then return Slider.Value end
        local SizeX = (Input.Position.X - RealSlider.Instance.AbsolutePosition.X) / TrackX
        return ((Slider.Max - Slider.Min) * SizeX) + Slider.Min
    end

    function Slider:Set(Value)
        local Raw = tonumber(Value)
        if not Raw or Raw ~= Raw or math.abs(Raw) == math.huge then
            Raw = Slider.Default
        end
        Slider.Value = CreatXRound(math.clamp(Raw, Slider.Min, Slider.Max), Slider.Decimals)

        SliderFill:Tween(
            { Size = UDim2.new(math.clamp((Slider.Value - Slider.Min) / math.max(1, Slider.Max - Slider.Min), 0, 1), 0, 1, 0) },
            TweenInfo.new((Library.Animation and Library.Animation.Time) or 0.1, Enum.EasingStyle.Quart, Enum.EasingDirection.Out))

        ValueLabel.Instance.Text = string.format("%s%s", Slider.Value, Slider.Suffix)

        Flags[Slider.Flag] = Slider.Value
        Library:SafeCall(Slider.Callback, Slider.Value)
    end

    function Slider:SetVisibility(Bool)
        Slider.Items["Holder"].Instance.Visible = Bool
    end

    function Slider:SetText(Text)
        if LabelEl then LabelEl.Instance.Text = tostring(Text) end
    end

    function Slider:OnChanged(Func) Slider.Changed = Func end
    function Slider:Display() Slider:Set(Slider.Value) end

    function Slider:SetValue(Str)
        local Num = tonumber(Str)
        if not Num then return end
        Slider:Set(Num)
    end

    RealSlider:Connect("InputBegan", function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
            Slider.Sliding = true
            Slider:Set(Slider:GetSize(Input))

            if InputChanged then return end
            InputChanged = Input.Changed:Connect(function()
                if Input.UserInputState == Enum.UserInputState.End then
                    Slider.Sliding = false
                    InputChanged:Disconnect()
                    InputChanged = nil
                end
            end)
        end
    end)

    Library:Connect(CN_UIS.InputChanged, function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch then
            if Slider.Sliding then
                Slider:Set(Slider:GetSize(Input))
            end
        end
    end)

    Slider:Set(Slider.Default)

    SetFlags[Slider.Flag] = function(Value)
        Slider:Set(Value)
    end

    return setmetatable(Slider, Library)
end

local function CreateDepBox(ParentSection)
    local Dep = {
        _children = {},
        _deps     = {},
        _section  = ParentSection,
    }

    local function AddChild(Obj)
        table.insert(Dep._children, Obj)
        return Obj
    end

    function Dep:AddToggle(Id, Data)
        Data = Data or {}
        local Cbs = {}
        local Wrapper
        local El = ParentSection:Toggle({
            Name     = Data.Text or Id,
            Flag     = Id,
            Default  = Data.Default or false,
            Tooltip  = Data.Tooltip,
            Callback = function(Value)
                for _, CB in ipairs(Cbs) do pcall(CB, Value) end
                if type(Data.Callback) == "function" then pcall(Data.Callback, Value) end
                SafeUpdateDeps()
            end,
        })
        Wrapper = WrapToggle(El, Id, Data.Default, Data.Callback)
        Wrapper._cbs = Cbs
        return AddChild(Wrapper)
    end

    function Dep:AddSlider(Id, Data)
        Data = Data or {}
        local Cbs = {}
        local Wrapper
        local El = CreateOutLawSlider(ParentSection, Id, {
            Text     = Data.Text or Id,
            Flag     = Id,
            Default  = Data.Default or 0,
            Min      = Data.Min or 0,
            Max      = Data.Max or 100,
            Rounding = Data.Rounding or 0,
            Suffix   = Data.Suffix,
            Tooltip  = Data.Tooltip,
            Compact  = Data.Compact,
            HideMax  = Data.HideMax,
            Callback = function(Value)
                for _, CB in ipairs(Cbs) do pcall(CB, Value) end
                if type(Data.Callback) == "function" then pcall(Data.Callback, Value) end
                SafeUpdateDeps()
            end,
        })
        Wrapper = WrapSlider(El, Id, Data.Default, Data.Callback)
        Wrapper._cbs = Cbs
        return AddChild(Wrapper)
    end

    function Dep:AddColorPicker(Id, Data)
        Data = Data or {}
        local DefaultColor = Data.Default or Color3.new(1, 1, 1)
        local LinCp = CreateLinoriaCp(Id, DefaultColor, Data.Callback)
        local NativeCp
        pcall(function()
            NativeCp = ParentSection:Colorpicker({
                Flag     = Id,
                Default  = DefaultColor,
                Callback = function() end,
            })
        end)
        if NativeCp then
            local Btn = NativeCp.Items and NativeCp.Items["ColorpickerButton"]
                and NativeCp.Items["ColorpickerButton"].Instance
            if Btn then
                local Sw = LinCp.Swatch
                Sw.Size = UDim2.new(1, 0, 1, 0)
                Sw.Position = UDim2.new(0, 0, 0, 0)
                Sw.Parent = Btn
                LinCp._anchorBtn = Btn
                Btn.MouseButton1Click:Connect(function()
                    LinCp:Toggle()
                end)
            end
            local Win = NativeCp.Items and NativeCp.Items["ColorpickerWindow"]
                and NativeCp.Items["ColorpickerWindow"].Instance
            if Win then
                Win.Visible = false
                pcall(function() Win.Parent = game:GetService("CoreGui") end)
            end
        else
            LinCp.Swatch.Parent = Library.Holder and Library.Holder.Instance
        end
        local Cp = { Value = DefaultColor, _id = Id, _cbs = {}, _lin = LinCp }
        function Cp:SetValue(v)
            LinCp:SetValue(v)
            Cp.Value = LinCp.Value
            for _, fn in ipairs(Cp._cbs) do pcall(fn, Cp.Value) end
        end
        function Cp:OnChanged(cb)
            if type(cb) == "function" then table.insert(Cp._cbs, cb) end
            LinCp:OnChanged(function(Color)
                Cp.Value = Color
                for _, fn in ipairs(Cp._cbs) do pcall(fn, Color) end
            end)
            return self
        end
        Toggles[Id] = Cp
        return AddChild(Cp)
    end

    function Dep:AddLabel(TextVal)
        local El = ParentSection:Label({ Name = TextVal })
        return AddChild(El)
    end

    function Dep:SetupDependencies(Deps)
        self._deps = Deps or {}
        self:Update()
    end

    function Dep:Update()
        local Visible = true
        for _, Pair in ipairs(self._deps) do
            local ToggleRef, ReqVal = Pair[1], Pair[2]
            local V = nil
            if type(ToggleRef) == "table" then
                V = ToggleRef.Value
            elseif type(ToggleRef) == "string" and Toggles[ToggleRef] then
                V = Toggles[ToggleRef].Value
            end
            if V ~= ReqVal then
                Visible = false
                break
            end
        end
        for _, Child in ipairs(self._children) do
            if Child and Child._el and Child._el.SetVisibility then
                pcall(function() Child._el:SetVisibility(Visible) end)
            elseif Child and Child.SetEnabled then
                pcall(function() Child:SetEnabled(Visible) end)
            end
        end
    end

    table.insert(AllDepBoxes, Dep)
    return Dep
end

