end

local function WrapTab(Page)
    local Tab = { _page = Page }
    local SubPages = {}

    local function BuildSubPage(Name, Opts)
        Opts = Opts or {}
        local SP = Page:SubPage({ Name = Name })
        local LS = SP:Section({ Name = Opts.Left or "Color",    Side = 1 })
        local RS = SP:Section({ Name = Opts.Right or "Settings", Side = 2 })
        local Sub = {
            _subpage = SP,
            _left = LS,
            _right = RS,
            _name = Name,
        }
        function Sub:AddLeftGroupbox(Title)
            return WrapGroupbox(LS, Title)
        end
        function Sub:AddMiddleGroupbox(Title)
            return WrapGroupbox(RS, Title)
        end
        function Sub:AddRightGroupbox(Title)
            return WrapGroupbox(RS, Title)
        end
        function Sub:AddLeftTabbox()
            return {
                AddTab = function(self, Name)
                    local S = SP:Section({ Name = Name or "Tab", Side = 1 })
                    return WrapGroupbox(S, Name)
                end,
            }
        end
        function Sub:AddRightTabbox()
            return {
                AddTab = function(self, Name)
                    local S = SP:Section({ Name = Name or "Tab", Side = 2 })
                    return WrapGroupbox(S, Name)
                end,
            }
        end
        return Sub
    end

    local function GetSubPage(Name, Opts)
        local S = SubPages[Name]
        if not S then
            S = BuildSubPage(Name, Opts)
            SubPages[Name] = S
        end
        return S
    end

    function Tab:AddLeftGroupbox(Title)
        return GetSubPage("Main"):AddLeftGroupbox(Title)
    end
    function Tab:AddMiddleGroupbox(Title)
        return GetSubPage("Main"):AddMiddleGroupbox(Title)
    end
    function Tab:AddRightGroupbox(Title)
        return GetSubPage("Main"):AddRightGroupbox(Title)
    end
    function Tab:AddLeftTabbox()
        return GetSubPage("Main"):AddLeftTabbox()
    end
    function Tab:AddRightTabbox()
        return GetSubPage("Main"):AddRightTabbox()
    end
    function Tab:AddSubPage(Name, Opts)
        return GetSubPage(Name or "Theme", Opts)
    end

    return Tab
end

local function WrapWindow(Window)
    local Win = { _window = Window }

    function Win:AddTab(Name, Icon)
        local Page = Window:Page({ Name = Name })
        return WrapTab(Page)
    end

    return Win
end

function adapter:CreateWindow(Data)
    Data = Data or {}
    local Window = Library:Window({
        Title      = Data.Title or "Menu",
        ButtonName = Data.ButtonName or "MENU",
    })
    pcall(function()
        local WI = Window.Items
        if not WI then return end
        local Hidden = {
            "HeaderFirstInline",
            "HeaderSecondInline",
            "HeaderThirdInline",
            "HeaderOutline",
            "HeaderInnerOutline",
            "HeaderTitle",
            "HeaderButtonHolder",
            "DockOutline",
        }
        for _, Key in ipairs(Hidden) do
            local Obj = WI[Key]
            if Obj and Obj.Instance then
                Obj.Instance.Visible = false
            end
        end
        -- The old SWG/OutLaw menu that ts work used to run on was 860x720;
        -- the window is 552x451. Scale the whole window (and all its
        -- rows/buttons/click zones) by ~1.55 to match the old size. The dropdown
        -- popup (OptionHolder) lives in the unscaled Holder, so it stays in the
        -- right size relative to the (scaled) button via Absolute*.
        local MF = WI["MainFrame"]
        if MF and MF.Instance and not MF.Instance:FindFirstChild("PanelScale") then
            local Sc = Instance.new("UIScale")
            Sc.Name = "PanelScale"
            Sc.Scale = 1
            Sc.Parent = MF.Instance
        end
    end)
    adapter.ScreenGui = (Library.Holder and Library.Holder.Instance) or adapter.ScreenGui
    adapter._window = Window
    adapter._allWindows = adapter._allWindows or {}
    table.insert(adapter._allWindows, Window)
    return WrapWindow(Window)
end

function adapter:UpdateDependencyBoxes()
    AllDepBoxesSync()
end
adapter.DependencyBoxes = AllDepBoxes

-- Auto-refresh wiring (see forward-declaration near ChainCallback).
function AllDepBoxesSync()
    for _, Dep in ipairs(AllDepBoxes) do
        pcall(function() Dep:Update() end)
    end
end
SafeUpdateDeps = AllDepBoxesSync

-- Lazily create the keybind-list widget, then proxy .Visible to it.
local KeybindUi = nil
local KeybindUiVisible = false
local function EnsureKeybindUi()
    if KeybindUi then return KeybindUi end
    pcall(function()
        if type(Library.KeybindList) == "function" then
            KeybindUi = Library:KeybindList({ Name = "Keybinds" })
        elseif type(Library.KeybindList) == "table" then
            KeybindUi = Library.KeybindList
        end
    end)
    return KeybindUi
end

do
    local Ui = EnsureKeybindUi()
    if Ui and Ui.SetVisibility then
        pcall(function() Ui:SetVisibility(false) end)
    end
end

adapter.KeybindFrame = newproxy(true)
do
    local KT = getmetatable(adapter.KeybindFrame)
    KT.__index = function(_, k)
        if k == "Visible" then return KeybindUiVisible end
        return nil
    end
    KT.__newindex = function(_, k, v)
        if k == "Visible" then
            KeybindUiVisible = (v == true)
            local Ui = EnsureKeybindUi()
            if Ui then
                pcall(function() Ui:SetVisibility(KeybindUiVisible) end)
            end
        end
    end
end

