local ThemeManager = { Folder = "outlaw/file" }
local PresetSnapshot = nil

local function ThemeToTable()
    local T = {}
    for K, C in pairs(Library.Theme) do
        T[K] = { math.floor(C.R * 255 + 0.5), math.floor(C.G * 255 + 0.5), math.floor(C.B * 255 + 0.5) }
    end
    return T
end

local function ApplyThemeTable(T)
    if type(T) ~= "table" then return end
    for K, RGB in pairs(T) do
        if type(RGB) == "table" and #RGB == 3 then
            Library:ChangeTheme(K, Color3.fromRGB(RGB[1], RGB[2], RGB[3]))
        end
    end
end

local function EnsureThemesDir()
    pcall(function()
        if makefolder then
            makefolder("outlaw/file")
            makefolder("outlaw/file/themes")
        end
    end)
end

local function ListThemes()
    local out = {}
    pcall(function()
        if listfiles then
            local files = listfiles("outlaw/file/themes")
            for _, f in ipairs(files) do
                local name = f:match("([^/\\]+)%.json$")
                if name then table.insert(out, name) end
            end
            table.sort(out)
        end
    end)
    return out
end

local AutoloadPath = "outlaw/file/themes/autoload.txt"

local function ReadAutoload()
    local name = ""
    pcall(function()
        if readfile then
            local ok, content = pcall(readfile, AutoloadPath)
            if ok and content and content ~= "" then
                name = content
            end
        end
    end)
    return name
end

local function WriteAutoload(Name)
    pcall(function()
        EnsureThemesDir()
        if writefile and Name and Name ~= "" then
            writefile(AutoloadPath, Name)
        end
    end)
end

local function BuildThemeUI(Section, ControlSection)
    if not PresetSnapshot then
        PresetSnapshot = ThemeToTable()
    end
    local Ctrl = ControlSection or Section
    local savedName = ""
    local dropdown

    for Key, Color in pairs(Library.Theme) do
        local Label = Section:Label({ Name = Key })
        pcall(function()
            local NativeCp = Label:Colorpicker({
                Flag     = "Theme_" .. tostring(Key),
                Default  = Color,
                Callback = function() end,
            })
            if NativeCp and NativeCp.Items then
                local Btn = NativeCp.Items["ColorpickerButton"]
                    and NativeCp.Items["ColorpickerButton"].Instance
                local LinCp = CreateLinoriaCp("Theme_" .. tostring(Key), Color, function(Value)
                    pcall(function() Library:ChangeTheme(Key, Value) end)
                end)
                if Btn then
                    local Sw = LinCp.Swatch
                    Sw.Size = UDim2.new(1, 0, 1, 0)
                    Sw.Position = UDim2.new(0, 0, 0, 0)
                    Sw.Parent = Btn
                    LinCp._anchorBtn = Btn
                end
                local Win = NativeCp.Items["ColorpickerWindow"]
                    and NativeCp.Items["ColorpickerWindow"].Instance
                if Win then
                    Win.Visible = false
                    pcall(function() Win.Parent = game:GetService("CoreGui") end)
                end
            end
        end)
    end

    Ctrl:Button({
        Name = "Reset Theme",
        Callback = function()
            if PresetSnapshot then
                ApplyThemeTable(PresetSnapshot)
            end
        end,
    })

    Ctrl:Textbox({
        Name = "Theme Name",
        Flag = "ThemeManagerName",
        Placeholder = "Theme name",
        Finished = true,
        Callback = function(Value)
            savedName = Value
        end,
    })

    Ctrl:Button({
        Name = "Save Theme",
        Callback = function()
            local name = savedName ~= "" and savedName or "default"
            EnsureThemesDir()
            local path = "outlaw/file/themes/" .. name .. ".json"
            pcall(function()
                if writefile then
                    writefile(path, HttpService:JSONEncode(ThemeToTable()))
                end
            end)
            -- Сразу применяем (лоадим) сохранённую тему одним нажатием.
            pcall(function()
                if readfile then
                    local ok, content = pcall(readfile, path)
                    if ok and content and content ~= "" then
                        local data = HttpService:JSONDecode(content)
                        ApplyThemeTable(data)
                        if dropdown then
                            dropdown:Refresh(ListThemes())
                        end
                    end
                end
            end)
        end,
    })

    dropdown = Ctrl:Dropdown({
        Name = "Saved Themes",
        Flag = "ThemeManagerDropdown",
        Items = ListThemes(),
        Callback = function(Value)
            savedName = Value
        end,
    })

    Ctrl:Toggle({
        Name = "Auto Load",
        Flag = "ThemeManagerAutoload",
        Default = ReadAutoload() ~= "",
        Callback = function(Value)
            if Value then
                WriteAutoload(savedName ~= "" and savedName or dropdown and dropdown.CurrentOption and dropdown.CurrentOption.Text or "")
            else
                pcall(function()
                    if writefile then writefile(AutoloadPath, "") end
                end)
            end
        end,
    })

end

ThemeManager.SetLibrary = function(self) return self end
ThemeManager.SetFolder = function(self, Folder)
    self.Folder = Folder or self.Folder
    return self
end
ThemeManager.SetOptionsTEMP = function(self) return self end
ThemeManager.IgnoreThemeSettings = function(self) return self end

ThemeManager.ApplyToTab = function(self, Tab)
    if not Tab or not Tab.AddLeftGroupbox then return self end
    local Groupbox = Tab:AddLeftGroupbox("Theming")
    local Section = Groupbox and Groupbox._section
    if Section then
        BuildThemeUI(Section)
    end
    return self
end

ThemeManager.ApplyToGroupbox = function(self, Groupbox)
    if not Groupbox or not Groupbox._section then return self end
    local Section = Groupbox._section
    BuildThemeUI(Section)
    return self
end

ThemeManager.ApplyToSubPage = function(self, Sub)
    if not Sub or not Sub._left then return self end
    BuildThemeUI(Sub._left, Sub._right)
    return self
end

ThemeManager.BuildConfigSection = function(self) return self end

ThemeManager.LoadAutoloadConfig = function(self)
    local name = ReadAutoload()
    if name and name ~= "" then
        self:Load(name)
    end
    return self
end

ThemeManager.Save = function(self, Name)
    if not Name or Name == "" then return end
    EnsureThemesDir()
    local path = "outlaw/file/themes/" .. tostring(Name) .. ".json"
    pcall(function()
        if writefile then
            writefile(path, HttpService:JSONEncode(ThemeToTable()))
        end
    end)
end

ThemeManager.Load = function(self, Name)
    if not Name or Name == "" then return end
    pcall(function()
        if readfile then
            local ok, content = pcall(readfile, "outlaw/file/themes/" .. tostring(Name) .. ".json")
            if ok and content and content ~= "" then
                ApplyThemeTable(HttpService:JSONDecode(content))
            end
        end
    end)
end

-- Linoria-style config manager backed by the core Library GetConfig/LoadConfig.
local SaveManager = {}
SaveManager.Folder = Library.Directory or "outlaw"
SaveManager.Folders = { Configs = (Library.Folders and Library.Folders.Configs) or "/Configs" }
SaveManager.Library = Library

function SaveManager:SetLibrary(lib) self.Library = lib or Library; return self end
function SaveManager:SetFolder(folder) self.Folder = folder or self.Folder; return self end
function SaveManager:SetOptionsTEMP() end
function SaveManager:IgnoreThemeSettings() return self end
function SaveManager:ApplyToTab() return self end
function SaveManager:ApplyToGroupbox() return self end

function SaveManager:GetFolder()
    return tostring(self.Folder or Library.Directory) .. tostring(self.Folders.Configs or "/Configs")
end

function SaveManager:GetPath(name)
    return self:GetFolder() .. "/" .. tostring(name) .. ".json"
end

function SaveManager:EnsureFolder()
    -- folder creation disabled
end

function SaveManager:GetConfigsList(Element)
    local Names = {}
    local ok, Files = pcall(function() return listfiles(self:GetFolder()) end)
    if ok and type(Files) == "table" then
        for _, File in ipairs(Files) do
            local Name = tostring(File):match("([^/\\]+)%.json$")
            if Name then table.insert(Names, Name) end
        end
    end
    if Element then
        if Element.Refresh then Element:Refresh(Names) end
        if Element.MaxSize ~= nil then Element.MaxSize = math.max(28, #Names * 18 + 14) end
    end
    return Names
end

function SaveManager:Save(Name)
    if not Name or Name == "" then return false, "no name" end
    self:EnsureFolder()
    return pcall(function()
        writefile(self:GetPath(Name), Library:GetConfig())
    end)
end

function SaveManager:Load(Name)
    if not Name or Name == "" then return false, "no name" end
    local ok, Content = pcall(function() return readfile(self:GetPath(Name)) end)
    if not ok or not Content or Content == "" then return false, "config not found" end
    return Library:LoadConfig(Content)
end

function SaveManager:Delete(Name)
    if not Name or Name == "" then return false, "no name" end
    return pcall(function()
        if isfile(self:GetPath(Name)) then delfile(self:GetPath(Name)) end
    end)
end

function SaveManager:SetAutoload(Name)
    pcall(function()
        if type(self.Folder) == "string" and self.Folder ~= "" and type(makefolder) == "function" and not isfolder(self.Folder) then
            makefolder(self.Folder)
        end
        writefile(tostring(self.Folder or Library.Directory) .. "/autoload.txt", tostring(Name or ""))
    end)
end

function SaveManager:LoadAutoloadConfig()
    local ok, Name = pcall(function()
        return readfile(tostring(self.Folder or Library.Directory) .. "/autoload.txt")
    end)
    if ok and Name and Name ~= "" then
        self:Load(Name)
    end
    return self
end

function SaveManager:BuildConfigSection(Tab)
    if not Tab or not Tab.AddLeftGroupbox then return self end

    local Box = Tab:AddLeftGroupbox("config")
    local Section = Box and Box._section
    if not Section then return self end

    self:EnsureFolder()

    local ConfigName
    local ConfigSelected

    local Dropdown = Section:Dropdown({
        Name = "Configs",
        Flag = "ConfigsDropdown",
        Items = {},
        Multi = false,
        Callback = function(Value)
            ConfigSelected = Value
        end,
    })

    Section:Textbox({
        Name = "Config name",
        Flag = "ConfigNameBox",
        Placeholder = "Config name",
        Callback = function(Value)
            ConfigName = Value
        end,
    })

    Section:Button({
        Name = "Create",
        Callback = function()
            if not ConfigName or ConfigName == "" then
                Library:Notification("Enter a config name", 3, Color3.fromRGB(255, 0, 0))
                return
            end
            local Ok, Err = self:Save(ConfigName)
            if Ok then
                self:GetConfigsList(Dropdown)
                Library:Notification("Successfully created config", 3, Color3.fromRGB(0, 255, 0))
            else
                Library:Notification("Failed to create config:\n" .. tostring(Err), 3, Color3.fromRGB(255, 0, 0))
            end
        end,
    })

    Section:Button({
        Name = "Save",
        Callback = function()
            if not ConfigSelected then
                Library:Notification("No config selected", 3, Color3.fromRGB(255, 0, 0))
                return
            end
            local Ok, Err = self:Save(ConfigSelected)
            if Ok then
                Library:Notification("Successfully saved config", 3, Color3.fromRGB(0, 255, 0))
            else
                Library:Notification("Failed to save config:\n" .. tostring(Err), 3, Color3.fromRGB(255, 0, 0))
            end
        end,
    })

    Section:Button({
        Name = "Load",
        Callback = function()
            if not ConfigSelected then
                Library:Notification("No config selected", 3, Color3.fromRGB(255, 0, 0))
                return
            end
            local Ok, Err = self:Load(ConfigSelected)
            if Ok then
                Library:Notification("Successfully loaded config", 3, Color3.fromRGB(0, 255, 0))
            else
                Library:Notification("Failed to load config:\n" .. tostring(Err), 3, Color3.fromRGB(255, 0, 0))
            end
        end,
    })

    Section:Button({
        Name = "Delete",
        Callback = function()
            if not ConfigSelected then
                Library:Notification("No config selected", 3, Color3.fromRGB(255, 0, 0))
                return
            end
            local Selected = ConfigSelected
            Library:OpenConfirmDialog({
                Title = "Delete config",
                Message = string.format('Delete "%s"? This permanently removes the file.', Selected),
                ConfirmText = "Delete",
                CancelText = "Keep",
                AccentColor = Color3.fromRGB(255, 95, 95),
                Callback = function(Confirmed)
                    if not Confirmed then return end
                    if not (isfile and isfile(self:GetPath(Selected))) then
                        Library:Notification("Config no longer exists", 3, Color3.fromRGB(255, 0, 0))
                        return
                    end
                    self:Delete(Selected)
                    ConfigSelected = nil
                    self:GetConfigsList(Dropdown)
                    Library:Notification("Successfully deleted config", 3, Color3.fromRGB(0, 255, 0))
                end,
            })
        end,
    })

    Section:Button({
        Name = "Refresh",
        Callback = function()
            self:GetConfigsList(Dropdown)
        end,
    })

    Section:Toggle({
        Name = "Autoload",
        Flag = "ConfigAutoload",
        Default = false,
        Callback = function(Value)
            if Value and ConfigSelected then
                self:SetAutoload(ConfigSelected)
            elseif not Value then
                self:SetAutoload("")
            end
        end,
    })

    return self
end

adapter.ThemeManager = ThemeManager
adapter.SaveManager = SaveManager
adapter.Library = Library
adapter.KeyList = Library.KeyList

return adapter, Toggles, Options
    end)()

return Lib, Tog, Opt
